-- DCG UE8 2009 – STAR FINANCE, gestion privée (données fictives, générées par tools/gen_dcg2009.py)

-- Date du jour simulée : 2009-05-15

-- Cours en euros (actions : par titre ; obligations : par euro de nominal).

PRAGMA foreign_keys = ON;

CREATE TABLE CLIENT (
  NumClient INTEGER PRIMARY KEY,
  Nom TEXT NOT NULL COLLATE NOCASE,
  Prenom TEXT NOT NULL COLLATE NOCASE,
  AdVille TEXT NOT NULL COLLATE NOCASE
);
CREATE TABLE CATEGORIE (
  NumCategorie INTEGER PRIMARY KEY,
  LibCategorie TEXT NOT NULL COLLATE NOCASE
);
CREATE TABLE COMPTE (
  NumCompte INTEGER PRIMARY KEY,
  DateCreation DATE NOT NULL,
  Fiscalite TEXT NOT NULL COLLATE NOCASE CHECK (Fiscalite IN ('PEA', 'Ordinaire')),
  NumClient INTEGER NOT NULL REFERENCES CLIENT(NumClient),
  NumCategorie INTEGER NOT NULL REFERENCES CATEGORIE(NumCategorie)
);
CREATE TABLE VALEUR (
  CodeValeur TEXT PRIMARY KEY COLLATE NOCASE,
  LibelleValeur TEXT NOT NULL COLLATE NOCASE,
  NominalValeur REAL NOT NULL,
  DateEmission DATE,
  DateEcheance DATE
);
CREATE TABLE OPERATION (
  NumOperation INTEGER PRIMARY KEY,
  DateOperation DATE NOT NULL,
  SensOperation TEXT NOT NULL COLLATE NOCASE CHECK (SensOperation IN ('Achat', 'Vente')),
  QuantiteNegociee REAL NOT NULL CHECK (QuantiteNegociee > 0),
  CoursNegocie REAL NOT NULL CHECK (CoursNegocie > 0),
  CodeValeur TEXT NOT NULL REFERENCES VALEUR(CodeValeur)
);
CREATE TABLE AFFECTER (
  NumOperation INTEGER NOT NULL REFERENCES OPERATION(NumOperation),
  NumCompte INTEGER NOT NULL REFERENCES COMPTE(NumCompte),
  QuantiteAff REAL NOT NULL CHECK (QuantiteAff > 0),
  PRIMARY KEY (NumOperation, NumCompte)
);
CREATE TABLE ARCH_OPE (
  NumOperation INTEGER PRIMARY KEY,
  DateOperation DATE NOT NULL,
  SensOperation TEXT NOT NULL COLLATE NOCASE CHECK (SensOperation IN ('Achat', 'Vente')),
  QuantiteNegociee REAL NOT NULL CHECK (QuantiteNegociee > 0),
  CoursNegocie REAL NOT NULL CHECK (CoursNegocie > 0),
  CodeValeur TEXT NOT NULL REFERENCES VALEUR(CodeValeur)
);

BEGIN TRANSACTION;







